import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CDA9RsCr.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"en/intro/quickstart.md","filePath":"en/intro/quickstart.md","lastUpdated":1794581028000}'),n={name:"en/intro/quickstart.md"};function i(l,e,s,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><h2 id="_1-download" tabindex="-1">1. Download <a class="header-anchor" href="#_1-download" aria-label="Permalink to &quot;1. Download&quot;">​</a></h2><p>Grab the build for your platform from <a href="https://github.com/aDarkMaker/BiliLuckyDraw/releases" target="_blank" rel="noreferrer">Releases</a>:</p><table tabindex="0"><thead><tr><th>Platform</th><th>File</th></tr></thead><tbody><tr><td>macOS (Apple Silicon / Intel)</td><td><code>BiliLuckyDraw-darwin-universal.zip</code></td></tr><tr><td>Windows</td><td><code>luckydraw-amd64-installer.exe</code> (installer) or <code>luckydraw.exe</code> (portable)</td></tr></tbody></table><p>If macOS blocks the first launch, open System Settings → Privacy &amp; Security and choose &quot;Open Anyway&quot;.</p><h2 id="_2-log-in" tabindex="-1">2. Log in <a class="header-anchor" href="#_2-log-in" aria-label="Permalink to &quot;2. Log in&quot;">​</a></h2><p>Pick one method:</p><ul><li><strong>Cookie login</strong> — copy the Bilibili Cookie from a browser, paste it into the box and click log in.</li><li><strong>QR login</strong> — switch to the QR tab, scan the code with the Bilibili mobile app and confirm on the phone.</li></ul><p>Credentials are stored only on this machine, in <code>~/.luckydraw/config.json</code>.</p><h2 id="_3-add-rooms" tabindex="-1">3. Add rooms <a class="header-anchor" href="#_3-add-rooms" aria-label="Permalink to &quot;3. Add rooms&quot;">​</a></h2><p>Open <strong>Settings → Lottery</strong> and enter the room IDs to monitor, or paste a live-room link such as <code>https://live.bilibili.com/12345</code>. Several rooms are fine; all participants merge into one pool.</p><p>Back on the lottery page, the room list on the right shows each room&#39;s cover, streamer and online count — click one to preview it.</p><h2 id="_4-start-the-draw" tabindex="-1">4. Start the draw <a class="header-anchor" href="#_4-start-the-draw" aria-label="Permalink to &quot;4. Start the draw&quot;">​</a></h2><p>On the lottery page set the keyword and winner count (1–9999), then click <strong>Start</strong>. As viewers send danmaku containing the keyword, the participant count rises:</p><ul><li>An empty keyword collects every danmaku.</li><li>The danmaku panel shows the current room&#39;s feed; scroll up to look back, and it returns to the newest line after a few seconds.</li><li>Click <strong>Stop</strong> when you&#39;re ready — the randomly picked winners appear at once and the draw is recorded in history.</li></ul><p>With many winners, the list scrolls inside its card and the page layout stays put.</p><h2 id="_5-review-and-export-history" tabindex="-1">5. Review and export history <a class="header-anchor" href="#_5-review-and-export-history" aria-label="Permalink to &quot;5. Review and export history&quot;">​</a></h2><p>The <strong>History</strong> tab lists draws for the active profile:</p><ul><li><strong>Export</strong> saves that draw as Markdown (<code>keyword-count-winners-time.md</code>).</li><li>Delete a single entry, or <strong>Delete all</strong> to clear the current profile&#39;s history.</li></ul><h2 id="_6-switch-appearance-and-language" tabindex="-1">6. Switch appearance and language <a class="header-anchor" href="#_6-switch-appearance-and-language" aria-label="Permalink to &quot;6. Switch appearance and language&quot;">​</a></h2><p>The <strong>Appearance</strong> tab switches light/dark, the background (default gradient / spring-festival / beach / your own image) and the language (中文 / English). Changes apply immediately and are remembered.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The sidebar collapses in narrow windows, and danmaku / winner scrollbars only appear while you scroll.</p></div>',22)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
